arguments.command:
python3 - <<'PY'
import glob,re,os,collections
files=glob.glob('/app/output/*.md')
texts={f:open(f,encoding='utf-8').read() for f in files}
alltext='\n'.join(texts.values())
# Defined IDs in headings or first table cell
pat=r'(?m)^(?:#{1,6}\s+|\|\s*)((?:MAP|VAL|NAV|ST|SEC|RPT)-[A-Za-z0-9-]+)'
defs=[]
for f,t in texts.items():
  for m in re.finditer(pat,t): defs.append((m.group(1),f,t[:m.start()].count('\n')+1))
c=collections.Counter(x[0] for x in defs)
print('DUPLICATE DEFINITIONS')
for k,v in sorted(c.items()):
  if v>1: print(k,v,[(os.path.basename(f),ln) for i,f,ln in defs if i==k])
print('BACKTICK REFS WITH NO EXACT DEFINITION')
for f,t in texts.items():
  for ln,line in enumerate(t.splitlines(),1):
    for r in re.findall(r'`((?:MAP|VAL|NAV|ST|SEC|RPT)-[A-Za-z0-9-]+)`',line):
      if r not in c: print(os.path.basename(f),ln,r,line.strip())
print('RANGE REFS (manual review)')
for f,t in texts.items():
  for ln,line in enumerate(t.splitlines(),1):
    if re.search(r'`(?:MAP|VAL|NAV|ST|SEC|RPT)-[^`]+`(?:至|—)',line) or re.search(r'`(?:MAP|VAL|NAV|ST|SEC|RPT)-[^`]+(?:至|—)[^`]+`',line):
      print(os.path.basename(f),ln,line.strip())
